head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF19000_FORM.xml";
//번역지원 화면 서식 추가 팝업
scwin.gLdMktTp = js_market; //세션의 시장구분
scwin.LastJob = "조회";
scwin.gRdoMktId;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '4' || scwin.gLdMktTp == '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        rdo_MKT_ID.setDisabled(true);
    } else {
        scwin.gRdoMktId = $c.frame.path("../").scwin.gRdoMktId;
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gRdoMktId);
        rdo_MKT_ID.setDisabled(false);
    }
    scwin.fn_setHeader();
};
scwin.fn_setHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ENG_TRANSL_OBJ_FORM_LIST";
    dts_Save.Reset();
    dts_Save.insertRow();
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_jongmok);
    var url = "/DsclSearchAll.do?method=listEngTranslObjForm";
    url += "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    //url += "&SCREN_ID=" + vScrenID;
    //url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    dts_jongmok.DataID = encodeURI(url);
    dts_jongmok.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    //gComAbbrv = dts_jongmok.NameString(eval(obj),"COM_ABBRV");
    gIsurCd = dts_jongmok.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_save = function() {
    if (txb_FormCd.getValue().length != 5) {
        $c.win.alert("서식 코드 5자리를 입력해주세요");
        img_com_srch.focus();
        return;
    }
    for (var i = 0; i < dts_jongmok.getTotalRow(); i++) {
        if (dts_jongmok.getCellData(i, "FORM_CD") == txb_FormCd.getValue()) {
            $c.win.alert("이미 등록된 서식입니다.");
            return;
        }
    }
    dts_Save.setCellData(1, "FORM_CD", txb_FormCd.getValue());
    dts_Save.setCellData(1, "FORM_VER", txb_FormVer.getValue());
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    dts_Save.setCellData(1, "LD_MKT_TP_CD", $c.stf.getObjectValue(rdo_MKT_ID));
    scwin.LastJob = "추가";
    trs_Save.Action = "/DsclSearchAll.do?method=addEngTranslObjForm" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};
scwin.fn_delete = function() {
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    dts_Save.setCellData(1, "LD_MKT_TP_CD", $c.stf.getObjectValue(rdo_MKT_ID));
    scwin.LastJob = "삭제";
    //dts_Save.UserStatus(1) = TB_JOB_DELETE;
    trs_Save.Action = "/DsclSearchAll.do?method=delEngTranslObjForm" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        $c.stf.showObj(panel_page, true);
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    } else {
        $c.stf.showObj(panel_page, false);
    }
    $c.cm.CloseWin(rowcount, grd_jongmok);
};
scwin.img_search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_add_onclick = function() {
    scwin.fn_save();
};
scwin.grd_jongmok_OnCheckClick = function(col, colid, bCheck) {
    //alert('grd_jongmok.OnCheckClick('+col+','+ colid+','+ bCheck+')');

};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(scwin.LastJob + " 실패");
    $c.stf.alert_error(trs_Save);
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_Search();
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert(scwin.LastJob + " 완료되었습니다.");
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_Search();
};
scwin.img_com_srch_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    scwin.gRdoMktId = $c.stf.getObjectValue(rdo_MKT_ID);
    var url = "./ULDSTF19000_FORM_POP.gfm";
    var winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 695, 575, "window");
};
scwin.img_delete_onclick = function() {
    cCnt = 0;
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        if (dts_jongmok.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
            break;
        }
    }
    if (cCnt == 0) {
        $c.win.alert("삭제할 서식을 선택해주세요.");
        return;
    } else {
        if (window.confirm("정말 삭제하시겠습니까?")) {
            var tmpInt = 1;
            for (var i = 1; i <= dts_jongmok.getTotalRow(); i++) {
                if (dts_jongmok.getCellData(i, "CHK_FLAG") == 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "FORM_CD", dts_jongmok.getCellData(i, "FORM_CD"));
                    dts_Save.setCellData(tmpInt, "FORM_VER", dts_jongmok.getCellData(i, "FORM_VER"));
                    tmpInt++;
                }
            }
            scwin.fn_delete();
        }
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_02);
    $c.data.downloadGridViewOffice(grd_jongmok, "영문번역대상서식 목록", "영문번역대상서식 목록" + ".xlsx", "8", 0);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
};
